// Writes apps/api/internal/rules/sessionresult/pow10_table_gen.go: the value `10 ** y` has in JavaScript for every exponent y the
// Most Improved / MVP expected win chance of computeAwards (packages/data/src/session-result/sessionResult.rules.ts) can reach.
//
// y is (opposing average level - own average level) / 2, each average being the sum of 1 to 5 level indexes (0 to 8) divided by the
// number of players, or 4 for an empty team. JavaScript leaves Math.pow / ** to the engine's math library, and it is not always the
// correctly rounded value (and Go's math.Pow differs from it too), so the values are captured here, not computed in Go.
//   source ~/.nvm/nvm.sh && nvm use && node apps/api/testdata/tools/gen-pow10-table.mjs
import { writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const averages = new Set([4])
for (let size = 1; size <= 5; size++) for (let sum = 0; sum <= 8 * size; sum++) averages.add(sum / size)
const view = new DataView(new ArrayBuffer(8))
const bits = (value) => {
  view.setFloat64(0, value)
  return `0x${view.getBigUint64(0).toString(16).padStart(16, '0')}`
}
const rows = new Map()
for (const own of averages)
  for (const other of averages) {
    const y = (other - own) / 2
    rows.set(bits(y), bits(10 ** y))
  }
const sorted = [...rows].sort(([a], [b]) => (a < b ? -1 : 1))
const body = sorted.map(([y, p]) => `\t{${y}, ${p}},`).join('\n')
writeFileSync(
  resolve(here, '../../internal/rules/sessionresult/pow10_table_gen.go'),
  `// Code generated by testdata/tools/gen-pow10-table.mjs; DO NOT EDIT.
// Source: ${process.release.name} ${process.version}, V8 ${process.versions.v8}, ${process.platform} ${process.arch}.

package sessionresult

// pow10Table maps the IEEE 754 bits of an exponent y to the bits of JavaScript's 10 ** y. Sorted by y.
var pow10Table = [...]struct{ y, pow uint64 }{
${body}
}
`,
)
console.log(sorted.length, 'exponents')
